using Avalonia;
using Avalonia.Controls;
using Avalonia.Headless;
using Avalonia.Interactivity;
using Avalonia.Threading;

namespace GuiEventsLab;

// WindowDriver: lets LabCheck use your window the way a person would,
// typing into boxes and clicking buttons, with no screen at all.
// Do not edit this file.
public class WindowDriver
{
    private static bool started;
    private readonly Window window;

    // Starts Avalonia without a screen. Safe to call more than once.
    public static void StartHeadless()
    {
        if (!started)
        {
            AppBuilder.Configure<App>()
                .UseHeadless(new AvaloniaHeadlessPlatformOptions { UseHeadlessDrawing = true })
                .SetupWithoutStarting();
            started = true;
        }
    }

    public WindowDriver(Window window)
    {
        this.window = window;
        window.Show();
        Flush();
    }

    // Replaces the text in a TextBox, the same as a person typing it.
    public void Type(string name, string text)
    {
        Find<TextBox>(name).Text = text;
        Flush();
    }

    // Clicks a Button. A disabled button ignores the click, as on screen.
    public void Click(string name)
    {
        Button button = Find<Button>(name);
        if (button.IsEffectivelyEnabled)
        {
            button.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));
        }
        Flush();
    }

    public bool IsEnabled(string name)
    {
        return Find<Control>(name).IsEnabled;
    }

    // The text a TextBlock or TextBox is showing, or (blank).
    public string Text(string name)
    {
        Control control = Find<Control>(name);
        string? text = null;
        if (control is TextBlock block)
        {
            text = block.Text;
        }
        else if (control is TextBox box)
        {
            text = box.Text;
        }
        return string.IsNullOrEmpty(text) ? "(blank)" : text;
    }

    // The items in a ListBox, joined with " | ", or (empty).
    public string Items(string name)
    {
        ListBox list = Find<ListBox>(name);
        List<string> items = new List<string>();
        foreach (object? item in list.Items)
        {
            items.Add(item?.ToString() ?? "");
        }
        return items.Count == 0 ? "(empty)" : string.Join(" | ", items);
    }

    // A control that does not exist yet means that part is not finished.
    private T Find<T>(string name) where T : Control
    {
        T? control = window.FindControl<T>(name);
        if (control == null)
        {
            throw new NotImplementedException($"The window has no {typeof(T).Name} named {name}.");
        }
        return control;
    }

    // Lets the window finish any work the last action queued up.
    private static void Flush()
    {
        Dispatcher.UIThread.RunJobs();
    }
}
